SELECT CASE WHEN amount >= 3700 THEN 'high' WHEN amount >= 1200 THEN 'mid' ELSE 'low' END AS amount_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values, ROUND((100 * SUM(CASE WHEN merchant = 'Lazada' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_lazada FROM transactions WHERE account_id IN (22, 26, 30) GROUP BY CASE WHEN amount >= 3700 THEN 'high' WHEN amount >= 1200 THEN 'mid' ELSE 'low' END
